CREATE TABLE public.hiring_question_snapshots (question_id uuid PRIMARY KEY REFERENCES public.question_bank(id) DEFERRABLE INITIALLY DEFERRED, created_at timestamptz NOT NULL DEFAULT now()); REVOKE ALL ON public.hiring_question_snapshots FROM anon,authenticated; GRANT SELECT ON public.hiring_question_snapshots TO authenticated; GRANT ALL ON public.hiring_question_snapshots TO service_role; ALTER TABLE public.hiring_question_snapshots ENABLE ROW LEVEL SECURITY; CREATE POLICY hiring_snapshots_staff_read ON public.hiring_question_snapshots FOR SELECT TO authenticated USING(public.is_hiring_staff(auth.uid()));
CREATE FUNCTION public.hiring_snapshot_category_step4() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.category='__job_snapshot' THEN NEW.category='other'; INSERT INTO public.hiring_question_snapshots(question_id) VALUES(NEW.id); END IF; RETURN NEW; END $$; REVOKE ALL ON FUNCTION public.hiring_snapshot_category_step4() FROM PUBLIC; CREATE TRIGGER hiring_snapshot_category_step4 BEFORE INSERT ON public.question_bank FOR EACH ROW EXECUTE FUNCTION public.hiring_snapshot_category_step4();